; =============================================================================
; lang/forth/bare/source.s: the embedded source text of the bare-metal image
; =============================================================================
; build/forth/corefs.s is generated by the Makefile from core.fs, tools.fs,
; see.fs and bare/start.fs: one .ascii line per source line. The kernel
; interprets it at power-on (plat_source says where it is).
        .far                            ; system memory
        .org  FAR_SRC                   ; after the I-LS mirror
core_fs:                                ; first byte of the text
        .include "corefs.s"             ; the text, as .ascii lines
core_fs_end:                            ; one past the last byte
